<template>
  <div class="myhelp">

    <!-- Header -->
    <div class="myhelp__header">
      <div style="width: 32px;" />
      <h1 class="myhelp__title">Моя помощь</h1>
     <button class="myhelp__info-btn" @click="showInfoSheet = true">
        <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
          <circle cx="12" cy="12" r="9.5" stroke="#111D33" stroke-width="1.5"/>
          <path d="M12 11V17" stroke="#111D33" stroke-width="1.5" stroke-linecap="round"/>
          <circle cx="12" cy="8" r="0.75" fill="#111D33" stroke="#111D33" stroke-width="0.5"/>
        </svg>
      </button>
    </div>

    <!-- Общая сумма -->
    <div class="myhelp__total-card" @click="router.push({ name: 'myhelp-details' })">
      <div class="myhelp__total-row">
        <span class="myhelp__total-label">Общая сумма помощи</span>
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
          <path d="M9 18L15 12L9 6" stroke="#888" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
        </svg>
      </div>
      <div class="myhelp__total-amount">
        <span class="myhelp__total-value">{{ totalAmount }}</span>
        <span class="myhelp__total-currency">₸</span>
      </div>
    </div>

    <!-- Мои товары -->
    <div class="myhelp__section">
      <h2 class="myhelp__section-title">Мои товары ({{ items.length }})</h2>

      <!-- Фильтры -->
      <div class="myhelp__filters">
        <button
          v-for="filter in filters"
          :key="filter.id"
          class="myhelp__filter-btn"
          :class="{ active: activeFilter === filter.id }"
          @click="activeFilter = filter.id"
        >
          {{ filter.name }}
        </button>
      </div>

      <!-- Пустое состояние -->
      <div v-if="filteredItems.length === 0" class="myhelp__empty">
        <div class="myhelp__empty-illustration">
