        </div>
      </div>

      <!-- Список товаров -->
      <div v-else class="myhelp__items">
        <div
          v-for="item in filteredItems"
          :key="item.id"
          class="myhelp__item-card"
          @click="router.push({ name: 'myhelp-product', params: { id: item.id } })"
        >
          <!-- Фото -->
          <img :src="item.image" :alt="item.name" class="myhelp__item-img" />

          <!-- Контент -->
          <div class="myhelp__item-content">
            <!-- Бейджи -->
           <div class="myhelp__item-badges">
 <span
  class="myhelp__item-badge"
  :class="{
    'myhelp__item-badge--reserved': getItemStatus(item) === 'reserved',
    'myhelp__item-badge--sold':     getItemStatus(item) === 'sold',
    'myhelp__item-badge--status':   getItemStatus(item) !== 'reserved' && getItemStatus(item) !== 'sold',
  }"
>
  {{ getItemStatus(item) === 'reserved' ? 'В резерве' : statusLabel(getItemStatus(item)) }}
</span>
 <span v-if="item.fund"
      class="myhelp__item-badge myhelp__item-badge--fund">
  {{ item.fundName }}
</span>
</div>

            <!-- Название -->
            <p class="myhelp__item-name">{{ item.name }}</p>

            <!-- Цены -->
            <div class="myhelp__item-prices">
              <span class="myhelp__item-price-current">
                {{ Number(item.sentToFund || Math.round(Number(item.price) * 0.8)).toLocaleString('ru-RU') }} ₸
              </span>
              <span class="myhelp__item-price-old">
                {{ Number(item.price).toLocaleString('ru-RU') }} ₸
              </span>
            </div>

            <!-- Локация и дата -->
            <div class="myhelp__item-meta">
              <div class="myhelp__item-location" v-if="item.location">
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none">
                  <path d="M12 2C8.13 2 5 5.13 5 9c0 5.25 7 13 7 13s7-7.75 7-13c0-3.87-3.13-7-7-7zm0 9.5c-1.38 0-2.5-1.12-2.5-2.5s1.12-2.5 2.5-2.5 2.5 1.12 2.5 2.5-1.12 2.5-2.5 2.5z" fill="#848484"/>
                </svg>
                <span>{{ item.location }}</span>
              </div>
              <span v-if="item.soldAt" class="myhelp__item-date">{{ item.soldAt }}</span>
            </div>
          </div>
        </div>
      </div>
    </div>

