<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import BottomNav from '../components/BottomNav.vue'

const showInfoSheet = ref(false)
const router = useRouter()
const activeFilter = ref('all')

const filters = [
  { id: 'all',       name: 'Все' },
  { id: 'review',    name: 'На оценке' },
  { id: 'sold',      name: 'Проданные' },
  { id: 'unsold',    name: 'Не проданные' }
]

const items = ref([])

const now = ref(Date.now())
let ticker = null


onMounted(() => {
  const raw = JSON.parse(localStorage.getItem('favorites') || '[]')
  
  // Обновляем статус в localStorage если резерв истёк
  let changed = false
  const updated = raw.map(item => {
    if (item.savedAt) {
      const elapsed = Math.floor((Date.now() - new Date(item.savedAt).getTime()) / 1000)
      if (elapsed >= 59 * 60 && item.status !== 'sold') {
        changed = true
        return { ...item, status: 'sold' }
      }
    }
    return item
  })
  
  if (changed) localStorage.setItem('favorites', JSON.stringify(updated))
  
  items.value = updated.map(item => ({
    ...item,
    status: item.status || 'review',
  }))

  ticker = setInterval(() => { now.value = Date.now() }, 1000)
})

onUnmounted(() => {
  clearInterval(ticker)
})
function getItemStatus(item) {
  if (item.savedAt) {
    const elapsed = Math.floor((now.value - new Date(item.savedAt).getTime()) / 1000)
    if (elapsed < 1 * 60) return 'reserved'
    return 'sold' // 👈 после истечения — Продан
  }
  return item.status || 'review'
}
function isReserveActive(savedAt) {
  const created = new Date(savedAt).getTime()
  const elapsed = Math.floor((Date.now() - created) / 1000)
  return elapsed < 59 * 60 // 59 минут
}

const filteredItems = computed(() => {
  let result = items.value

  if (activeFilter.value !== 'all') {
    result = result.filter(i => {
      const status = getItemStatus(i)
      if (activeFilter.value === 'unsold') {
        return status !== 'sold' && status !== 'reserved'
      }
      return status === activeFilter.value
    })
  }

  return result
})

const totalAmount = computed(() => {
  return items.value
    .reduce((sum, i) => sum + (Number(i.price) || 0), 0)
    .toLocaleString('ru-RU')
})

function statusLabel(status) {
  const map = {
    review:    'На оценке',
    sold:      'Продан',
    unsold:    'Не продан',
    cancelled: 'Снят с продажи',
  }
  return map[status] ?? status
}
function startReserveTimer(savedAt) {
  const created = new Date(savedAt).getTime()
  const total = 59 * 60

  const tick = () => {
    const elapsed = Math.floor((Date.now() - created) / 1000)
    reserveTimer.value = Math.max(total - elapsed, 0)

    if (reserveTimer.value <= 0) {
      clearInterval(reserveInterval)
      isSaved.value = false
      reserveExpired.value = true

      // 👈 Обновляем статус в localStorage
      const raw = JSON.parse(localStorage.getItem('favorites') || '[]')
      const idx = raw.findIndex(i => String(i.id) === String(route.params.id))
      if (idx !== -1) {
        raw[idx].status = 'sold'
        localStorage.setItem('favorites', JSON.stringify(raw))
        item.value = { ...item.value, status: 'sold' }
      }
    }
  }

  tick()
  reserveInterval = setInterval(tick, 1000)
}
</script>

